/* Read-only visual teaching layer. Canonical scenario entries and battle records stay unchanged. */
(function(){'use strict';
const R=()=>window.RULES_DATA||{},E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko,tag='span')=>`<${tag} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</${tag}>`,P=pair=>window.MMRuleTerms?.prose(...pair,{edition:'n26'})||L(...pair,'p'),valid=r=>r?.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26';
function resolve(row,kind,options={}){if(!['scenarioEntries','sideJobs'].includes(kind)||String(options.edition||row?.edition_slug||row?.edition).toLowerCase()!=='n26'||!valid(row)||row.is_custom||row.reference_custom_description||row.reference_description_cleared)return null;const source=kind==='sideJobs'?(R().scenarioEntries||[]).find(e=>e.side_job_id===row.id):(R().scenarioEntries||[]).find(e=>e.id===row.id);if(!valid(source))return null;const key=source.id.replace(/^official-003-scenario-entry-/,'');const guide=window.MMScenarioGuideData?.[key];return guide?{source,key,guide}:null;}
const txt=(x,y,en,ko,extra='')=>`<text x="${x}" y="${y}" text-anchor="middle" ${extra} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</text>`;
const frame=body=>`<svg viewBox="0 0 360 260" class="sg-board" aria-hidden="true" focusable="false"><rect x="12" y="12" width="336" height="236" rx="6" class="sg-board-base"/>${body}</svg>`;
const centre=()=>'<path d="M174 130h12m-6-6v12" class="sg-centre"/>';
function token(x,y,side,ignored=false){return `<g class="sg-token sg-side-${side.toLowerCase()}${ignored?' is-ignored':''}">${side==='A'?`<circle cx="${x}" cy="${y}" r="12"/>`:`<rect x="${x-12}" y="${y-12}" width="24" height="24" rx="3"/>`}<text x="${x}" y="${y+4}" text-anchor="middle" data-i18n-ignore>${ignored?'×':side}</text></g>`;}
const turfCases={
 a:{label:['Only A in the area','A만 있음'],a:2,b:0,round:3,result:['A wins this central condition','중앙 조건으로 A 승리'],why:['At round 3’s End-phase check, A has two qualifying models inside and B has none.','3라운드 종료 단계 승리 확인 때 원 안의 유효 모델이 A 2개·B 0개입니다.']},
 b:{label:['Only B in the area','B만 있음'],a:0,b:1,round:3,result:['B wins this central condition','중앙 조건으로 B 승리'],why:['The condition works symmetrically: B alone has a qualifying model inside.','반대로 B만 유효 모델이 있으면 B가 승리합니다.']},
 both:{label:['A 2 vs B 1','A 2개·B 1개'],a:2,b:1,round:3,result:['No central winner · continue','중앙 승리 없음 · 계속 진행'],why:['A has more models, but B still has one qualifying model inside. Both sides are present.','A가 더 많아도 B의 유효 모델 1개가 남아 있습니다. 양쪽 다 있으므로 중앙 승리가 아닙니다.']},
 injured:{label:['B’s model is injured','B가 중상인 경우'],a:1,b:0,ignored:1,round:3,result:['A wins this central condition','중앙 조건으로 A 승리'],why:['B’s only model in the circle is Seriously Injured (or Seriously Damaged), so it is ignored. Only A counts.','원 안의 B 모델이 중상(차량이라면 중손상)이므로 제외합니다. 판정에 포함되는 것은 A뿐입니다.']},
 empty:{label:['Neither in the area','원 안에 아무도 없음'],a:0,b:0,round:3,result:['No central winner · continue','중앙 승리 없음 · 계속 진행'],why:['Both sides still have models outside the circle, but neither has a qualifying model inside.','양쪽 모두 원 밖에는 모델이 남아 있지만 원 안의 유효 모델은 없습니다.']},
 early:{label:['Same position in round 2','2라운드라면?'],a:2,b:0,round:2,result:['The central check has not started','중앙 조건 확인은 아직 시작 전'],why:['This central victory condition begins in round 3. Being alone in the circle in round 2 does not satisfy that timing.','중앙 승리 조건은 3라운드부터입니다. 2라운드에 혼자 들어와 있어도 확인 시점 조건을 충족하지 않습니다.']}
};
function turfStage(key='both'){const c=turfCases[key]||turfCases.both,inside=[...Array(c.a)].map((_,i)=>token(145,105+i*52,'A')).join('')+[...Array(c.b)].map((_,i)=>token(212,170-i*48,'B')).join('')+(c.ignored?token(212,170,'B',true):'');return `<div class="sg-turf-stage">${frame(`<circle cx="180" cy="130" r="84" class="sg-zone"/><line x1="180" y1="130" x2="264" y2="130" class="sg-distance"/>${txt(228,121,'9″','9″')}${centre()}${txt(180,149,'Centre','중심')}${inside}${token(39,53,'A')}${token(321,207,'B')}${txt(72,33,'Outside','원 밖')}${txt(288,239,'Outside','원 밖')}`)}<div class="sg-counts"><span class="sg-a">A: ${c.a}</span><span class="sg-b">B: ${c.b}</span>${c.ignored?L('× = ignored','× = 판정 제외'):''}<span>${L('Round','라운드')} ${c.round}</span></div><div class="sg-outcome ${c.a&&c.b===0&&c.round>=3||c.b&&c.a===0&&c.round>=3?'is-win':''}" aria-live="polite">${L(...c.result,'strong')}${P(c.why)}</div></div>`;}
function turf(){return `<div class="sg-turf"><h4>${L('Change the example','상황을 눌러 비교해 보세요')}</h4><div class="sg-cases" role="group" aria-label="Turf War examples" data-i18n-en-aria-label="Turf War examples" data-i18n-ko-aria-label="터프 워 상황 예시">${Object.entries(turfCases).map(([key,c])=>`<button type="button" data-sg-case="${key}" aria-pressed="${key==='both'}">${L(...c.label)}</button>`).join('')}</div><div data-sg-stage>${turfStage()}</div><p class="sg-caption">${L('Dashed circle: radius 9 inches, diameter 18. Both sides also have one model outside the circle in every example. Schematic, not to scale.','점선 원은 반경 9인치·지름 18인치입니다. 모든 예시에서 양쪽 모두 원 밖에도 모델 1개씩 남아 있다고 가정합니다. 축척 없는 도식입니다.')}</p><div class="sg-legend"><span class="sg-a">● A</span><span class="sg-b">■ B</span>${L('× Seriously Injured / Seriously Damaged: ignore','× 중상·중손상: 제외')}</div></div>`;}
function placement(g){let body='',caption;
 if(g.diagram==='opposite-zones'){const y=130-g.gap*4;body=`<rect x="14" y="14" width="332" height="${y-14}" class="sg-fill-a"/><rect x="14" y="${260-y}" width="332" height="${y-14}" class="sg-fill-b"/><line x1="14" y1="130" x2="346" y2="130" class="sg-dash"/>${txt(180,39,'A deployment','A 배치 구역')}${txt(180,232,'B deployment','B 배치 구역')}<line x1="48" y1="${y}" x2="48" y2="130" class="sg-distance"/>${txt(82,(y+130)/2+4,g.gap+'″',g.gap+'″')}${txt(246,124,'Central line','중앙선')}${txt(180,167,'No deployment','배치 제외 구간')}`;caption=[`Each boundary is ${g.gap} inches from the central line. The gap between them is ${g.gap*2} inches.`,`중앙선에서 양쪽 경계까지 각각 ${g.gap}인치, 두 경계 사이 합계 ${g.gap*2}인치입니다.`];}
 else if(g.diagram==='ambush'){body=`<rect x="14" y="14" width="332" height="232" class="sg-fill-a"/><circle cx="180" cy="130" r="103" class="sg-exclusion"/><circle cx="180" cy="130" r="52" class="sg-fill-b"/><circle cx="180" cy="130" r="103" class="sg-dash"/>${centre()}${txt(180,109,'Defender','방어자')}${txt(180,153,'Within 6″','6인치 이내')}${txt(180,47,'12″ boundary','12인치 경계')}${txt(75,233,'Attacker: ≥12″','공격자: 12인치 이상')}`;caption=['Defender: inner circle. Attacker: outside the outer circle. The ring in between is not either side’s deployment zone.','방어자는 안쪽 원, 공격자는 바깥 원 밖입니다. 두 원 사이 띠는 어느 쪽 배치 구역도 아닙니다.'];}
 else if(g.diagram==='quarters'){body=`<rect x="14" y="14" width="166" height="116" class="sg-fill-a"/><rect x="180" y="130" width="166" height="116" class="sg-fill-b"/><line x1="180" y1="14" x2="180" y2="246" class="sg-dash"/><line x1="14" y1="130" x2="346" y2="130" class="sg-dash"/><circle cx="180" cy="130" r="73" class="sg-exclusion"/>${centre()}${txt(67,45,'A quarter','A 사분면')}${txt(287,231,'B quarter','B 사분면')}${txt(180,114,'Keep ≥9″','9인치 이상')}`;caption=['Example: upper-left versus lower-right. The central 9-inch area is excluded even within your chosen quarter.','왼쪽 위와 오른쪽 아래를 택한 예시입니다. 자기 사분면이어도 중심 9인치 안쪽은 제외합니다.'];}
 else{body=`<path d="M14 14h77a77 77 0 0 1-77 77Z M346 246h-77a77 77 0 0 1 77-77Z" class="sg-fill-a"/><path d="M346 14v77a77 77 0 0 1-77-77Z M14 246v-77a77 77 0 0 1 77 77Z" class="sg-fill-b"/>${txt(40,45,'A','A')}${txt(319,231,'A','A')}${txt(319,45,'B','B')}${txt(40,231,'B','B')}${txt(180,119,'Each corner zone: 9″','각 모서리: 9인치')}${txt(180,147,'Split the crew evenly','크루를 균등 배분')}`;caption=['A uses one diagonal pair; B uses the other. Each zone is measured from its own corner.','A는 대각선 한 쌍, B는 나머지 한 쌍입니다. 각 구역은 해당 모서리를 기준으로 잽니다.'];}
 return `<figure class="sg-figure">${frame(body)}<figcaption>${L(...caption)} ${L('Not to scale.','축척 없는 도식입니다.')}</figcaption></figure>`;}
function objectives(g){const dot=(x,y,label,side='a')=>`<g class="sg-objective sg-side-${side}"><circle cx="${x}" cy="${y}" r="15"/><text x="${x}" y="${y+5}" text-anchor="middle" data-i18n-ignore>${label}</text></g>`;let body='',caption;
 if(g.diagram==='one-objective'){body=dot(180,130,'1')+txt(180,178,'Central objective','중앙 목표');caption=['One central objective. Control at the End-phase check: +1 VP; win at 3 VP.','중앙 목표 1개를 종료 단계 승리 확인 때 통제하면 +1VP, 먼저 3VP면 승리합니다.'];}
 else if(g.diagram==='three-objectives'){body=dot(180,130,'1')+dot(92,68,'2')+dot(268,195,'3')+txt(180,232,'Control 2 → +1 VP','2개 통제 → +1VP');caption=['Positions of the additional objectives are examples. Keep at least 6 inches between objectives and from edges.','추가 목표 위치는 예시입니다. 목표끼리와 가장자리에서 최소 6인치를 띄우세요.'];}
 else if(g.diagram==='opposite-objectives'){body=dot(180,52,'1')+dot(180,208,'2')+`<line x1="215" y1="14" x2="215" y2="52" class="sg-distance"/><line x1="215" y1="208" x2="215" y2="246" class="sg-distance"/>`+txt(240,40,'6″','6″')+txt(240,235,'6″','6″')+txt(180,126,'Control both','둘 다 통제')+txt(180,151,'+1 VP','+1VP');caption=['Both objectives are 6 inches inward from opposite edge midpoints.','두 목표는 서로 반대편 가장자리 중앙에서 각각 안쪽 6인치입니다.'];}
 else{body=`<rect x="14" y="14" width="332" height="83" class="sg-fill-b"/><rect x="14" y="163" width="332" height="83" class="sg-fill-a"/>`+txt(180,36,'B deployment zone','B 배치 구역')+txt(180,238,'A deployment zone','A 배치 구역')+[82,180,278].map(x=>dot(x,65,'A','a')+dot(x,196,'B','b')).join('')+txt(180,124,'Control → remove → +1 VP','통제 → 제거 → +1VP')+txt(180,147,'Win at 2 VP','목표 2VP');caption=['A places three objectives in B’s zone; B places three in A’s zone. Zone shapes and marker positions are illustrative.','A는 B 구역에 3개, B는 A 구역에 3개를 놓습니다. 구역 형태와 목표 위치는 예시입니다.'];}
 return `<figure class="sg-figure">${frame(body)}<figcaption>${L(...caption)} ${L('Not to scale.','축척 없는 도식입니다.')}</figcaption></figure>`;}
function crew(g){const c=g.crew,formula=(chosen,random,label)=>`<div class="sg-formula"><h4>${L(...label)}</h4><div class="sg-number-flow"><div>${L('Choose','직접 선택','small')}<b>${chosen}</b></div>${random?`<span aria-hidden="true">+</span><div>${L('Random','무작위','small')}<b>${random}</b></div>`:''}<span aria-hidden="true">→</span><div>${L('Starting crew','시작 크루','small')}<b>${typeof chosen==='number'&&typeof random==='number'?chosen+random:chosen+(random?' + '+random:'')}</b></div></div></div>`;return formula(c.chosen,c.random,c.defender?['Attacker','공격자']:['Both players','양쪽 플레이어'])+(c.defender?formula(3,0,['Defender','방어자']):'')+(c.deck?`<div class="sg-note">${L('Separate reinforcement deck','별도 증원 덱','strong')}<p>${c.deck} ${L('cards · D3 per End phase from round 1','장 · 1라운드부터 매 종료 단계 D3명')}</p></div>`:'');}
function formula(){return `<div class="sg-number-flow sg-vp-formula"><div>${L('Enemy OOA','적 OOA','small')}<b>1</b></div><span>+</span><div>${L('Leader / Champion / Brute','리더·챔피언·브루트','small')}<b>1</b></div><span>+</span><div>${L('Fight / Coup de Grace / Sabotage','파이트·쿠 드 그라스·사보타주','small')}<b>1</b></div><span>=</span><div><small>VP</small><b>3</b></div></div><p class="sg-caption">${L('Example where both bonuses apply. A missing bonus is 0.','두 보너스가 모두 적용되는 예시입니다. 해당하지 않는 보너스는 0으로 계산합니다.')}</p>`;}
function markup(row,kind,options={}){const found=resolve(row,kind,options);if(!found)return '';const {source,key,guide:g}=found;const visual=g.diagram==='turf'?turf():g.diagram==='crew'?crew(g):g.diagram==='vp-formula'?formula():g.diagram==='job'?'':g.diagram.endsWith('objective')||g.diagram.endsWith('objectives')?objectives(g):placement(g);const links=(g.links||[]).map(id=>(R().coreRules||[]).find(r=>valid(r)&&r.id===id)).filter(Boolean);
 return `<section class="scenario-guide" data-scenario-guide="${E(source.id)}"><p class="sg-eyebrow">${L('See how this mission works','그림과 예시로 이해하기')}</p><div class="sg-summary">${P(g.summary)}</div><div class="sg-layout ${visual?'':'sg-no-visual'}">${visual?`<div class="sg-visual">${visual}</div>`:''}<div class="sg-reading"><h4>${L('Follow this order','이 순서로 진행하세요')}</h4><ol class="sg-steps">${g.steps.map(step=>`<li>${L(...step.title,'strong')}${P(step.body)}</li>`).join('')}</ol>${g.control?`<aside class="sg-note sg-control">${L('What does “control” mean?','‘통제’는 어떻게 확인하나요?','strong')}${P(['Within 3 inches of the objective centre: at least one friendly non-Pet Fighter and no enemy models. Ignore Seriously Injured/Damaged models. Enemy Pets and Vehicles can still contest.','목표 중심 3인치 안에 펫이 아닌 아군 파이터가 1명 이상 있고 적 모델이 없어야 합니다. 중상·중손상 모델은 무시하지만 적 펫·차량도 통제를 방해할 수 있습니다.'])}</aside>`:''}<aside class="sg-example">${L('Worked example','실제 상황 예시','strong')}${P(g.example)}</aside>${g.caution?`<p class="sg-caution">${L(...g.caution)}</p>`:''}</div></div>${source.rule_data?.sole_remaining_player_wins?`<aside class="sg-note sg-ending">${L('Also check the whole battlefield','전장 전체의 종료 조건도 확인','strong')}${P(['If only one side has models left on the battlefield, that side wins. If neither side has models, draw. This is separate from the central area or objective count.','전장에 한쪽 모델만 남으면 그쪽이 승리하고 양쪽 모두 없으면 무승부입니다. 중앙 원이나 목표 주변의 모델 수와 전장 전체의 잔존 모델 수를 구분하세요.'])}</aside>`:''}${links.length?`<nav class="sg-links">${L('Related rules','관련 판정 규칙','strong')}${links.map(r=>`<button type="button" class="btn small" data-sg-rule="${E(r.id)}">${L(r.name,r.name_ko||r.name)}</button>`).join('')}</nav>`:''}<p class="sg-caption">${L('Examples explain the rule; they do not record a win, VP or rewards.','이 화면은 설명용 예시입니다. 승패·VP·보상을 기록하지 않습니다.')}</p></section>`;
}
window.addEventListener('click',e=>{const button=e.target.closest?.('[data-sg-case],[data-sg-rule]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(button.dataset.sgRule)return window.MMRuleReference?.open('coreRules',button.dataset.sgRule,{edition:'n26',activator:button,nested:true});const root=button.closest('.sg-turf'),key=button.dataset.sgCase;if(!root||!turfCases[key])return;root.querySelectorAll('[data-sg-case]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));root.querySelector('[data-sg-stage]').innerHTML=turfStage(key);window.UKI18n?.refresh(root);},true);
window.MMScenarioGuide={markup,resolve};
})();
